"""Document and payment service."""
import hashlib
import hmac
import re
import secrets
import threading

try:
    from gateway import GatewayTimeout
except ImportError:  # pragma: no cover - gateway module normally provided
    class GatewayTimeout(Exception):
        pass

_USERNAME_RE = re.compile(r"[a-z0-9_]{3,32}")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


class Service:
    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._lock = threading.RLock()
        self._users = {}      # username -> (salt, hash)
        self._tokens = {}     # token -> (username, created)
        self._docs = {}       # doc_id -> record dict (with private "_seq")
        self._user_docs = {}  # username -> [doc_id, ...] in creation order
        self._doc_counter = 0
        self._cursors = {}    # cursor -> (username, last_seq)
        self._payments = {}   # username -> [payment, ...]
        self._pay_keys = {}   # (username, key) -> {"amount": int, "payment": dict|None}
        self._pay_counter = 0

    # ---------- helpers ----------
    @staticmethod
    def _hash(salt, password):
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 10000)

    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if self._clock.now() < created + self._ttl:
            return user
        return None

    @staticmethod
    def _public(doc):
        return {k: v for k, v in doc.items() if not k.startswith("_")}

    @staticmethod
    def _valid_doc_fields(title, content):
        return (isinstance(title, str) and 1 <= len(title) <= 200
                and isinstance(content, str) and len(content) <= 100000)

    def _owned(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        doc = self._docs.get(doc_id)
        if doc is None or doc["owner"] != user:
            return None
        return doc

    def _user_doc_records(self, user):
        return [self._docs[i] for i in self._user_docs.get(user, [])]

    # ---------- authentication ----------
    def register(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not _USERNAME_RE.fullmatch(username):
                return 400, None
            if not isinstance(password, str) or len(password) < 8:
                return 400, None
            if username in self._users:
                return 409, None
            salt = secrets.token_bytes(16)
            self._users[username] = (salt, self._hash(salt, password))
            return 201, None

    def login(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not isinstance(password, str):
                return 401, None
            entry = self._users.get(username)
            if entry is None:
                return 401, None
            salt, digest = entry
            if not hmac.compare_digest(digest, self._hash(salt, password)):
                return 401, None
            token = secrets.token_hex(16)
            while token in self._tokens:
                token = secrets.token_hex(16)
            self._tokens[token] = (username, self._clock.now())
            return 200, {"token": token}

    def logout(self, token):
        with self._lock:
            if self._auth(token) is None:
                return 401, None
            del self._tokens[token]
            return 204, None

    # ---------- documents ----------
    def create_document(self, token, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not self._valid_doc_fields(title, content):
                return 400, None
            self._doc_counter += 1
            doc_id = "doc-%d" % self._doc_counter
            self._docs[doc_id] = {
                "id": doc_id,
                "owner": user,
                "title": title,
                "content": content,
                "created_at": self._clock.now(),
                "_seq": self._doc_counter,
            }
            self._user_docs.setdefault(user, []).append(doc_id)
            return 201, {"id": doc_id}

    def get_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            doc = self._owned(user, doc_id)
            if doc is None:
                return 404, None
            return 200, self._public(doc)

    def update_document(self, token, doc_id, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            doc = self._owned(user, doc_id)
            if doc is None:
                return 404, None
            if not self._valid_doc_fields(title, content):
                return 400, None
            doc["title"] = title
            doc["content"] = content
            return 200, self._public(doc)

    def delete_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            doc = self._owned(user, doc_id)
            if doc is None:
                return 404, None
            del self._docs[doc_id]
            self._user_docs[user].remove(doc_id)
            return 204, None

    def list_documents(self, token, page_size=20, cursor=None):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(page_size) or not 1 <= page_size <= 100:
                return 400, None
            after = 0
            if cursor is not None:
                if not isinstance(cursor, str):
                    return 400, None
                entry = self._cursors.get(cursor)
                if entry is None or entry[0] != user:
                    return 400, None
                after = entry[1]
            remaining = [d for d in self._user_doc_records(user) if d["_seq"] > after]
            page = remaining[:page_size]
            next_cursor = None
            if len(remaining) > page_size:
                next_cursor = secrets.token_hex(16)
                self._cursors[next_cursor] = (user, page[-1]["_seq"])
            return 200, {"items": [self._public(d) for d in page],
                         "next_cursor": next_cursor}

    def search_documents(self, token, query):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not isinstance(query, str) or query == "":
                return 400, None
            q = query.lower()
            hits = [self._public(d) for d in self._user_doc_records(user)
                    if q in d["title"].lower() or q in d["content"].lower()]
            return 200, hits

    def export_documents(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [self._public(d) for d in self._user_doc_records(user)]

    # ---------- payments ----------
    def pay(self, token, amount_cents, idempotency_key):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(amount_cents) or not 1 <= amount_cents <= 1000000:
                return 400, None
            if not isinstance(idempotency_key, str):
                return 400, None
            state_key = (user, idempotency_key)
            state = self._pay_keys.get(state_key)
            if state is None:
                state = {"amount": amount_cents, "payment": None}
                self._pay_keys[state_key] = state
            elif state["amount"] != amount_cents:
                return 409, None
            elif state["payment"] is not None:
                return 200, dict(state["payment"])
            # new or pending (earlier attempt timed out): charge with a stable reference
            reference = "%s:%s" % (user, idempotency_key)
            try:
                self._gateway.charge(reference, amount_cents)
            except GatewayTimeout:
                return 504, None
            self._pay_counter += 1
            payment = {
                "id": "pay-%d" % self._pay_counter,
                "amount_cents": amount_cents,
                "idempotency_key": idempotency_key,
                "created_at": self._clock.now(),
            }
            state["payment"] = payment
            self._payments.setdefault(user, []).append(payment)
            return 201, dict(payment)

    def list_payments(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(p) for p in self._payments.get(user, [])]

