import pytest
from hypothesis import given, settings, strategies as st

from solution import Service

PW = "password123"
SETTINGS = dict(max_examples=40, deadline=None)


class _Clock:
    def __init__(self, t=1000.0):
        self.t = t

    def now(self):
        return self.t


class _Gateway:
    def charge(self, reference, amount_cents):
        return {"status": "ok"}


def _env(ttl=100):
    clock = _Clock()
    return Service(clock, _Gateway(), token_ttl=ttl), clock


def _login(svc, name="alice"):
    assert svc.register(name, PW)[0] == 201
    out = svc.login(name, PW)
    assert out[0] == 200, f"input={name!r} output={out!r}"
    return out[1]["token"]


def _bad_token(svc, clock, kind):
    if kind == "none":
        return None
    if kind == "unknown":
        return "never-issued-token"
    tok = svc.login("alice", PW)[1]["token"]
    if kind == "revoked":
        assert svc.logout(tok)[0] == 204
    else:
        clock.t += 100.0
    return tok


def _op(svc, name, tok, doc_id):
    if name == "get":
        return svc.get_document(tok, doc_id)
    if name == "update":
        return svc.update_document(tok, doc_id, "new title", "new content")
    return svc.delete_document(tok, doc_id)


@pytest.mark.parametrize("target", ["existing", "missing"])
@pytest.mark.parametrize("kind", ["none", "unknown", "revoked", "expired"])
@pytest.mark.parametrize("name", ["get", "update", "delete"])
def test_doc_access_with_bad_token_returns_exactly_401(name, kind, target):
    """get, update and delete return 401 for a missing, unknown, revoked or expired token, whether or not the document exists."""
    svc, clock = _env()
    good = _login(svc)
    out = svc.create_document(good, "title", "content")
    assert out[0] == 201, f"output={out!r}"
    doc_id = out[1]["id"] if target == "existing" else "no-such-doc"
    # keep a still-valid token for the later check (login before expiry)
    tok = _bad_token(svc, clock, kind)
    out = _op(svc, name, tok, doc_id)
    assert out[0] == 401, f"input={(name, kind, target)!r} output={out!r}"
