import hashlib
import hmac
import re
import secrets
import threading

try:
    from gateway import GatewayTimeout
except ImportError:  # pragma: no cover - gateway module normally provided
    class GatewayTimeout(Exception):
        pass

_USERNAME_RE = re.compile(r"[a-z0-9_]{3,32}")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


class Service:
    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._lock = threading.RLock()
        self._users = {}      # username -> (salt, hash)
        self._tokens = {}     # token -> (username, created)
        self._docs = {}       # doc_id -> record dict (with private "_seq")
        self._user_docs = {}  # username -> [doc_id, ...] in creation order
        self._doc_counter = 0
        self._cursors = {}    # cursor -> (username, last_seq)
        self._payments = {}   # username -> [payment, ...]
        self._pay_keys = {}   # (username, key) -> {"amount": int, "payment": dict|None}
        self._pay_counter = 0

    # ---------- helpers ----------
    @staticmethod
    def _hash(salt, password):
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 10000)

    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if self._clock.now() < created + self._ttl:
            return user
        return None

    @staticmethod
    def _public(doc):
        return {k: v for k, v in doc.items() if not k.startswith("_")}

    @staticmethod
    def _valid_doc_fields(title, content):
        return (isinstance(title, str) and 1 <= len(title) <= 200
                and isinstance(content, str) and len(content) <= 100000)

    def _owned(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        doc = self._docs.get(doc_id)
        if doc is None or doc["owner"] != user:
            return None
        return doc

    def _user_doc_records(self, user):
        return [self._docs[i] for i in self._user_docs.get(user, [])]

    # ---------- authentication ----------
    def register(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not _USERNAME_RE.fullmatch(username):
                return 400, None
            if not isinstance(password, str) or len(password) < 8:
                return 400, None
            if username in self._users:
                return 409, None
            salt = secrets.token_bytes(16)
            self._users[username] = (salt, self._hash(salt, password))
            return 201, None

    def login(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not isinstance(password, str):
                return 401, None
            entry = self._users.get(username)
            if entry is None:
                return 401, None
            salt, digest = entry
            if not hmac.compare_digest(digest, self._hash(salt, password)):
                return 401, None
            token = secrets.token_hex(16)
            while token in self._tokens:
                token = secrets.token_hex(16)
            self._tokens[token] = (username, self._clock.now())
            return 200, {"token": token}

