    def create_document(self, token, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not self._valid_doc_fields(title, content):
                return 400, None
            self._doc_counter += 1
            doc_id = "doc-%d" % self._doc_counter
            self._docs[doc_id] = {
                "id": doc_id,
                "owner": user,
                "title": title,
                "content": content,
                "created_at": self._clock.now(),
                "_seq": self._doc_counter,
            }
            self._user_docs.setdefault(user, []).append(doc_id)
            return 201, {"id": doc_id}

    def get_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            doc = self._owned(user, doc_id)
            if doc is None:
                return 404, None
            return 200, self._public(doc)

    def update_document(self, token, doc_id, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            doc = self._owned(user, doc_id)
            if doc is None:
                return 404, None
            if not self._valid_doc_fields(title, content):
                return 400, None
            doc["title"] = title
            doc["content"] = content
            return 200, self._public(doc)

