        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(page_size) or not 1 <= page_size <= 100:
                return 400, None
            after = 0
            if cursor is not None:
                if not isinstance(cursor, str):
                    return 400, None
                entry = self._cursors.get(cursor)
                if entry is None or entry[0] != user:
                    return 400, None
                after = entry[1]
            remaining = [d for d in self._user_doc_records(user) if d["_seq"] > after]
            page = remaining[:page_size]
            next_cursor = None
            if len(remaining) > page_size:
                next_cursor = secrets.token_hex(16)
                self._cursors[next_cursor] = (user, page[-1]["_seq"])
            return 200, {"items": [self._public(d) for d in page],
                         "next_cursor": next_cursor}

    def search_documents(self, token, query):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not isinstance(query, str) or query == "":
                return 400, None
            q = query.lower()
            hits = [self._public(d) for d in self._user_doc_records(user)
                    if q in d["title"].lower() or q in d["content"].lower()]
            return 200, hits

    def export_documents(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [self._public(d) for d in self._user_doc_records(user)]

    # ---------- payments ----------
    def pay(self, token, amount_cents, idempotency_key):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(amount_cents) or not 1 <= amount_cents <= 1000000:
                return 400, None
            if not isinstance(idempotency_key, str):
                return 400, None
            state_key = (user, idempotency_key)
            state = self._pay_keys.get(state_key)
            if state is None:
                state = {"amount": amount_cents, "payment": None}
                self._pay_keys[state_key] = state
            elif state["amount"] != amount_cents:
                return 409, None
            elif state["payment"] is not None:
                return 200, dict(state["payment"])
            # new or pending (earlier attempt timed out): charge with a stable reference
            reference = "%s:%s" % (user, idempotency_key)
            try:
                self._gateway.charge(reference, amount_cents)
            except GatewayTimeout:
                return 504, None
            self._pay_counter += 1
            payment = {
                "id": "pay-%d" % self._pay_counter,
                "amount_cents": amount_cents,
                "idempotency_key": idempotency_key,
                "created_at": self._clock.now(),
            }
            state["payment"] = payment
            self._payments.setdefault(user, []).append(payment)
            return 201, dict(payment)

    def list_payments(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(p) for p in self._payments.get(user, [])]
